#include <bits/stdc++.h>
using namespace std;

static char buf[1 << 16];
static size_t blen = 0, bpos = 0;
static inline int gc() {
    if (bpos == blen) {
        blen = fread(buf, 1, sizeof buf, stdin);
        bpos = 0;
        if (!blen) return -1;
    }
    return buf[bpos++];
}
static long long readLong() {
    int c = gc();
    while (c != '-' && (c < '0' || c > '9')) {
        if (c == -1) return 0;
        c = gc();
    }
    bool neg = false;
    if (c == '-') { neg = true; c = gc(); }
    long long v = 0;
    while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
    return neg ? -v : v;
}

int main() {
    int n = (int)readLong();
    vector<long long> values(n);
    long long sum = 0;
    for (auto &v : values) { v = readLong(); sum += v; }
    vector<int> L(n), R(n);
    for (int i = 0; i < n; i++) { L[i] = (int)readLong(); R[i] = (int)readLong(); }
    // BFS order from the root; processing it in reverse handles children before parents.
    vector<int> order;
    order.reserve(n);
    order.push_back(0);
    for (size_t i = 0; i < order.size(); i++) {
        int u = order[i];
        if (L[u] != -1) order.push_back(L[u]);
        if (R[u] != -1) order.push_back(R[u]);
    }
    vector<long long> gain(n, 0);
    vector<int> dir(n, -1);
    bool hasBest = false;
    long long best = 0;
    int center = 0;
    for (int k = (int)order.size() - 1; k >= 0; k--) {
        int u = order[k];
        long long lg = (L[u] != -1 && gain[L[u]] > 0) ? gain[L[u]] : 0;
        long long rg = (R[u] != -1 && gain[R[u]] > 0) ? gain[R[u]] : 0;
        long long through = values[u] + lg + rg;
        if (!hasBest || through > best) { hasBest = true; best = through; center = u; }
        if (lg >= rg && lg > 0) { dir[u] = L[u]; gain[u] = values[u] + lg; }
        else if (rg > 0) { dir[u] = R[u]; gain[u] = values[u] + rg; }
        else gain[u] = values[u];
    }
    // Rebuild: left downward chain reversed, then the center, then the right chain.
    vector<int> path;
    if (L[center] != -1 && gain[L[center]] > 0)
        for (int u = L[center]; u != -1; u = dir[u]) path.push_back(u);
    reverse(path.begin(), path.end());
    path.push_back(center);
    if (R[center] != -1 && gain[R[center]] > 0)
        for (int u = R[center]; u != -1; u = dir[u]) path.push_back(u);
    string out = to_string(sum) + "\n" + to_string(best) + "\n";
    for (size_t i = 0; i < path.size(); i++) { if (i) out += ' '; out += to_string(values[path[i]]); }
    out += '\n';
    for (size_t i = 0; i < path.size(); i++) { if (i) out += ' '; out += to_string(path[i]); }
    out += '\n';
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;

