        for (int i = 0; i < size; i++) {
            int u = order[i];
            if (L[u] != -1) order[size++] = L[u];
            if (R[u] != -1) order[size++] = R[u];
        }
        long[] gain = new long[n];
        int[] dir = new int[n];
        java.util.Arrays.fill(dir, -1);
        boolean hasBest = false;
        long best = 0;
        int center = 0;
        for (int k = size - 1; k >= 0; k--) {
            int u = order[k];
            long lg = (L[u] != -1 && gain[L[u]] > 0) ? gain[L[u]] : 0;
            long rg = (R[u] != -1 && gain[R[u]] > 0) ? gain[R[u]] : 0;
            long through = values[u] + lg + rg;
            if (!hasBest || through > best) { hasBest = true; best = through; center = u; }
            if (lg >= rg && lg > 0) { dir[u] = L[u]; gain[u] = values[u] + lg; }
            else if (rg > 0) { dir[u] = R[u]; gain[u] = values[u] + rg; }
            else gain[u] = values[u];
        }
        // Rebuild: left downward chain reversed, then the center, then the right chain.
        int[] path = new int[n];
