package main

import (
	"bufio"
	"os"
	"slices"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int64 {
	c, err := rd.ReadByte()
	for err == nil && c != '-' && (c < '0' || c > '9') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return 0
	}
	neg := false
	if c == '-' {
		neg = true
		c, err = rd.ReadByte()
	}
	var v int64
	for err == nil && c >= '0' && c <= '9' {
		v = v*10 + int64(c-'0')
		c, err = rd.ReadByte()
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	n := int(readInt())
	values := make([]int64, n)
	var sum int64
	for i := range values {
		values[i] = readInt()
		sum += values[i]
	}
	L, R := make([]int, n), make([]int, n)
	for i := 0; i < n; i++ {
		L[i], R[i] = int(readInt()), int(readInt())
	}
	// BFS order from the root; processing it in reverse handles children before parents.
	order := make([]int, 1, n)
	for i := 0; i < len(order); i++ {
		u := order[i]
		if L[u] != -1 {
			order = append(order, L[u])
		}
		if R[u] != -1 {
			order = append(order, R[u])
		}
	}
	gain := make([]int64, n)
	dir := make([]int, n)
	for i := range dir {
		dir[i] = -1
	}
	hasBest, best, center := false, int64(0), 0
	for k := len(order) - 1; k >= 0; k-- {
		u := order[k]
		var lg, rg int64
		if L[u] != -1 && gain[L[u]] > 0 {
			lg = gain[L[u]]
		}
		if R[u] != -1 && gain[R[u]] > 0 {
			rg = gain[R[u]]
		}
		through := values[u] + lg + rg
		if !hasBest || through > best {
			hasBest, best, center = true, through, u
		}
		if lg >= rg && lg > 0 {
			dir[u], gain[u] = L[u], values[u]+lg
		} else if rg > 0 {
			dir[u], gain[u] = R[u], values[u]+rg
		} else {
			gain[u] = values[u]
		}
	}
	// Rebuild: left downward chain reversed, then the center, then the right chain.
	var path []int
	if L[center] != -1 && gain[L[center]] > 0 {
		for u := L[center]; u != -1; u = dir[u] {
			path = append(path, u)
		}
	}
	slices.Reverse(path)
	path = append(path, center)
	if R[center] != -1 && gain[R[center]] > 0 {
		for u := R[center]; u != -1; u = dir[u] {
			path = append(path, u)
		}
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	buf := strconv.AppendInt(nil, sum, 10)
	buf = append(buf, '\n')
	buf = strconv.AppendInt(buf, best, 10)
	buf = append(buf, '\n')
	for i, u := range path {
		if i > 0 {
			buf = append(buf, ' ')
		}
		buf = strconv.AppendInt(buf, values[u], 10)
	}
	buf = append(buf, '\n')
	for i, u := range path {
		if i > 0 {
			buf = append(buf, ' ')
		}
		buf = strconv.AppendInt(buf, int64(u), 10)
	}
	buf = append(buf, '\n')
	w.Write(buf)
}
